"""Islamiat (Ikhtiari) XII PDF64: pp.118–119 — selected ahadith 26, 27. Run: python class12_iski_page064.py"""
from class12_iski_common import BOOK, Builder, rec, P, AR


def p64():
    b = Builder()
    b.h('Special study of selected ahadith', 'منتخب احادیث کا خصوصی مطالعہ:', 'د غوره احادیثو ځانګړې مطالعه')
    b.h('Hadith no. 26', 'حدیث نمبر 26', 'حدیث نمبر ۲۶')
    AR(b, 'عَنْ بَهْزِ بْنِ حَكِيْمٍ عَنْ اَبِيْهِ عَنْ جَدِّهٖ رَضِيَ اللّٰهُ عَنْهُمْ قَالَ سَمِعْتُ رَسُوْلَ اللّٰهِ صَلَّى اللّٰهُ عَلَيْهِ وَآلِهٖ وَسَلَّمَ يَقُوْلُ: وَيْلٌ لِّلَّذِيْ يُحَدِّثُ بِالْحَدِيْثِ لِيُضْحِكَ بِهِ الْقَوْمَ فَيَكْذِبُ وَيْلٌ لَّهٗ وَيْلٌ لَّهٗ', 'سنن الترمذی')
    b.p('Translation: Bahz bin Hakim narrates from his father, and he from his grandfather, that I heard the Messenger of Allah ﷺ; he ﷺ was saying: Ruin is for that person who tells lies to make his people laugh. Ruin is for him, ruin is for him.', 'ترجمہ: بہز بن حکیم اپنے والد اور وہ ان کے دادا سے روایت کرتے ہیں کہ میں نے رسول اکرم صلی اللہ علیہ وآلہٖ وسلم سے سنا، آپ صلی اللہ علیہ وآلہٖ وسلم فرما رہے تھے: ہلاکت ہے اس شخص کے لئے جو اپنی قوم کو ہنسانے کے لئے جھوٹ بولتا ہے۔ ہلاکت ہے اس کے لئے، ہلاکت ہے اس کے لئے۔', 'ژباړه: بهز بن حکیم له خپل پلار او هغه له خپل نیکه روایت کوي چې ما د الله له رسول ﷺ واورېدل، فرمایل یې: هلاکت دی د هغه چا لپاره چې خپل قوم د خندولو لپاره دروغ وايي. هلاکت دی د هغه لپاره، هلاکت دی د هغه لپاره.')
    b.h('Explanation', 'تشریح', 'تشریح')
    P(b, [('In this blessed hadith the Noble Prophet ﷺ has given a warning to those people who tell lies in gatherings of their relatives and friends etc. to win applause. Islam has cursed the liar. The sense of another blessed saying of the Noble Prophet ﷺ is that in a believer there can be evil of every kind, but he cannot be a liar. In the same way, telling the signs of the hypocrites, the saying of the Noble Prophet ﷺ is that one of his signs is also this, that when he speaks he tells a lie.', 'اس حدیثِ مبارکہ میں نبی اکرم صلی اللہ علیہ وآلہٖ وسلم نے ان لوگوں کو وعید سنائی ہے جو اپنے عزیز و اقارب اور دوستوں وغیرہ کی محفلوں میں جھوٹ بول کر داد وصول کرتے ہیں۔ اسلام نے جھوٹے شخص پر لعنت کی ہے۔ نبی اکرم صلی اللہ علیہ وآلہٖ وسلم کے ایک اور ارشادِ گرامی کا مفہوم ہے کہ مومن میں ہر قسم کی برائی ہو سکتی ہے لیکن وہ جھوٹا نہیں ہو سکتا۔ اسی طرح منافقین کی نشانیاں بتاتے ہوئے نبی اکرم صلی اللہ علیہ وآلہٖ وسلم کا ارشاد ہے کہ اس کی ایک نشانی یہ بھی ہے کہ جب وہ بات کرتا ہے تو جھوٹ بولتا ہے۔', 'په دې مبارک حدیث کې نبي اکرم ﷺ هغو خلکو ته ګواښ کړی چې د خپلو خپلوانو او ملګرو په غونډو کې دروغ وايي او ستاینه ترلاسه کوي. اسلام پر دروغجن لعنت کړی. د نبي اکرم ﷺ د بل مبارک ارشاد مفهوم دا دی چې په مؤمن کې هر ډول بدي کېدای شي، خو دروغجن نشي کېدای. همداسې د منافقانو د نښو په ښوولو کې د نبي اکرم ﷺ ارشاد دی چې د هغه یوه نښه دا هم ده چې کله خبرې کوي، دروغ وايي.'),
          ('It has generally been seen that people tell lies to become the life of the gathering, and often merely for amusement. They take the support of false information, and merely to please others for the moment they make up things from their own side …', 'عام طور پر دیکھا گیا ہے کہ محفل کی جان بننے کے لیے اور بسا اوقات محض تفریحِ طبع کے لیے لوگ جھوٹ بولتے ہیں۔ جھوٹی معلومات کا سہارا لیتے ہیں اور محض دوسروں کو وقتی طور پر خوش کرنے کے لیے اپنی طرف سے من گھڑت باتیں', 'عموماً لیدل شوي چې خلک د غونډې د روح ګرځېدو لپاره، او ډېر ځله یوازې د ساعت‌تېرۍ لپاره دروغ وايي. د دروغو معلوماتو ملاتړ اخلي، او یوازې د نورو د لنډمهاله خوشالولو لپاره له ځانه جوړې خبرې …')])
    r1 = rec(b, 2, 118, 64, [118])
    t = Builder()
    P(t, [('… make. A severe warning has been given for such people that ruin is for them. By ruin is meant that they will remain in loss in this world too, and success in the Hereafter too will not come to their share.', 'کرتے ہیں۔ ایسے لوگوں کے لیے سخت وعید سنائی گئی ہے کہ ان کی ہلاکت ہے۔ ہلاکت سے مراد یہ ہے کہ وہ اس دنیا میں بھی خسارے میں رہیں گے اور اخروی فلاح بھی ان کے حصے میں نہیں آئے گی۔', '… جوړوي. د داسې خلکو لپاره سخت ګواښ اورول شوی چې هلاکت یې دی. له هلاکت مراد دا دی چې په دې نړۍ کې به هم په تاوان کې وي، او د آخرت بریا به یې هم په برخه نشي.'),
          ('Therefore we should always hold fast to truth, and never tell a lie, nor ever adopt this low habit for amusement. We should always keep this matter in mind, that we are the followers of the Prophet "as-Sadiq" (the Truthful). We should make truthfulness our way of life.', 'لہٰذا ہمیں چاہیے کہ ہم ہمیشہ سچ کا دامن تھامے رہیں اور کبھی بھی جھوٹی بات نہ کریں اور نہ ہی کبھی تفریحِ طبع کے لیے اس گھٹیا عادت کو اپنائیں۔ ہمیں ہمیشہ یہ بات اپنے ذہن میں رکھنی چاہیے کہ ہم ”الصادق“ نبی کے امتی ہیں۔ ہمیں چاہیے کہ سچائی کو اپنا شیوہ بنائیں۔', 'نو موږ باید تل رښتیا ټینګ ونیسو، هېڅکله دروغ ونه وایو، او نه هېڅکله د ساعت‌تېرۍ لپاره دا ټیټه عادت غوره کړو. موږ باید تل دا خبره په ذهن کې ولرو چې موږ د «الصادق» نبي امتیان یو. موږ باید رښتینولي خپله شیوه وګرځوو.')])
    t.h('Hadith no. 27', 'حدیث نمبر 27', 'حدیث نمبر ۲۷')
    AR(t, 'عَنْ مَكْحُوْلٍ رَحِمَهُ اللّٰهُ اَنَّ رَسُوْلَ اللّٰهِ صَلَّى اللّٰهُ عَلَيْهِ وَآلِهٖ وَسَلَّمَ قَالَ: اَلْعِلْمُ بِالتَّعَلُّمِ وَالْخَيْرُ عَادَةٌ وَاِذَا اَرَادَ اللّٰهُ بِهٖ خَيْرًا فَقَّهَهٗ فِي الدِّيْنِ', 'الجامع فی الحدیث: 446، مولفہ عبداللہ بن وہب المصری')
    t.p('Translation: Knowledge comes by learning, and goodness is a nature (habit). And when Allah the Exalted intends good for someone, He grants him understanding of the religion.', 'ترجمہ: علم سیکھنے سے آتا ہے اور بھلائی فطرت ہے۔ اور جب اللہ تعالیٰ کسی سے بھلائی کا ارادہ کرتا ہے تو اسکو دین کی سمجھ عطا کر دیتا ہے۔', 'ژباړه: علم په زده‌کړې راځي، او ښېګڼه فطرت (عادت) ده. او کله چې الله تعالی د چا سره د ښېګڼې اراده وکړي، هغه ته د دین پوهه ورکوي.')
    t.h('Explanation', 'تشریح', 'تشریح')
    P(t, [('In this blessed hadith he ﷺ said that the promotion, spread and progress of knowledge happens only when it is taught to others. Those societies and nations make the most progress where the process of teaching and instruction continues. In this pure hadith goodness has been declared a habit. Its meaning is that goodness becomes firm in a person\'s behaviour only when it becomes his habit — that is, in daily affairs and routines he goes on doing good deeds involuntarily. And in this way a time comes when his morals become excellent.', 'اس حدیثِ مبارکہ میں آپ صلی اللہ علیہ وآلہٖ وسلم نے فرمایا کہ علم کی ترویج و اشاعت اور ترقی اسی وقت ہوتی ہے جب دوسروں کو سکھایا جائے۔ وہ معاشرے اور قومیں زیادہ ترقی کرتی ہیں جہاں درس و تدریس کا عمل جاری رہتا ہے۔ اس حدیثِ پاک میں نیکی کو عادت قرار دیا گیا ہے۔ اس کا مطلب یہ ہے کہ نیکی اس وقت انسان کے رویّے میں پختہ ہوتی ہے جب وہ اس کی عادت بن جاتی ہے۔ یعنی روزمرہ معاملات اور معمولات میں وہ غیر ارادی طور پر نیکیاں کرتا چلا جاتا ہے۔ اور اس طرح ایک وقت آتا ہے جب اس کے اخلاق بہترین بن جاتے ہیں۔', 'په دې مبارک حدیث کې هغه ﷺ وفرمایل چې د علم خپراوی او پرمختګ هغه وخت کېږي چې نورو ته وښوول شي. هغه ټولنې او قومونه ډېر پرمختګ کوي چې هلته د درس او تدریس عمل جاري وي. په دې پاک حدیث کې نېکي عادت ګڼل شوې. مطلب یې دا دی چې نېکي هغه وخت د انسان په چلند کې پخه کېږي چې د هغه عادت شي — یعنې په ورځنیو چارو او معمولاتو کې بې‌ارادې نېکۍ کوي. او په دې ډول یو وخت راځي چې اخلاق یې غوره کېږي.'),
          ('In this blessed hadith it has also been said that when Allah intends good for someone, He grants him understanding of the religion. As it were, the understanding of the religion of Islam is a very great reward from Allah the Exalted. Fortunate are those individuals whom Allah the Exalted …', 'اس حدیثِ مبارکہ میں یہ بھی فرمایا گیا ہے کہ جب اللہ کسی کے ساتھ بھلائی کا ارادہ فرماتا ہے تو اسے دین کا فہم عطا کر دیتا ہے۔ گویا دینِ اسلام کا فہم اللہ تعالیٰ کی طرف سے بہت بڑا انعام ہے۔ خوش قسمت ہیں وہ افراد جنہیں اللہ تعالیٰ', 'په دې مبارک حدیث کې دا هم ویل شوي چې کله الله د چا سره د ښېګڼې اراده وکړي، هغه ته د دین پوهه ورکوي. ګواکې د اسلام د دین پوهه د الله تعالی له لوري ډېر لوی انعام دی. بختور دي هغه کسان چې الله تعالی …')])
    BOOK.save(64, [(2, r1), (2, rec(t, 2, 119, 64, [119]))], issues=[{'id': 'iski12-pdf064', 'unit': 2, 'printedPage': 118,
               'description': 'Selected ahadith begin at no. 26 as printed (numbering continues from the Class 11 book). Student marks and brackets on pp.118–119 excluded. Hadith 27 reference printed as "(الجامع فی الحدیث: 446، مولفہ عبداللہ بن وہب المصری)".'}])


if __name__ == '__main__':
    p64()
